# --- XvB Donation Controller (Issues #9, #70) ---
# Closed-loop controller. The raffle pays nothing above a tier threshold, so the
# objective is: hold XvB's *reported* 1h average just above the tier on minimum
# donation, send everything else to p2pool, and never donate so much that p2pool
# stops finding shares (which would forfeit "VIP" status — non-VIP winners are
# skipped and failed). It steers off XvB's own hard numbers and self-calibrates,
# so it holds the tier regardless of how XvB scales our donation. Validated by the
# closed-loop simulator in mining_dashboard/sim/donation_model.py.

# Hard ceiling on the donated fraction, independent of the VIP reserve below. A
# last-resort cap so a misconfigured/zero difficulty reading can never donate the
# whole cycle.
XVB_MAX_DONATION_FRACTION = float(os.environ.get("XVB_MAX_DONATION_FRACTION", 0.85))

# Cushion held above the tier threshold: the controller targets the 1h average at
# threshold * (1 + pct), capped in ABSOLUTE H/s. The raffle terminates a win if the
# 1h average dips below the round minimum, so we sit a small, noise-covering margin
# above it — not a percentage of the tier (which wastes more the higher the tier).
XVB_MAINT_MARGIN_PCT = float(os.environ.get("XVB_MAINT_MARGIN_PCT", 0.03))
XVB_MAINT_MARGIN_ABS_CAP = float(os.environ.get("XVB_MAINT_MARGIN_ABS_CAP", 1000))

# Integral gain of the calibration loop. Each cycle the donated fraction is nudged
# by gain * (reference - measured_1h) / current_hr. Low by design: the 1h average
# is laggy, so high gain hunts (the simulator finds oscillation above ~0.05,
# especially if XvB over-credits). 0.03 converges in a few hours and stays stable.
XVB_CONTROL_GAIN = float(os.environ.get("XVB_CONTROL_GAIN", 0.03))

# Age past which a frozen XvB stats read is treated as stale (#311). A successful
# fetch lands every ~10 poll cycles (data_service throttle) and only a real fetch
# bumps `last_update` (#136), so its age IS the fetch age. When the fetch goes quiet
# (e.g. a stuck Tor circuit) `avg_1h` freezes; steering off that frozen number
# over-donates against a target we can't refresh. Past this age the controller holds
# the last split instead of chasing it. Default ~3 fetch intervals.
XVB_STATS_STALE_AFTER_S = float(os.environ.get("XVB_STATS_STALE_AFTER_S", 3 * 10 * UPDATE_INTERVAL))

# Fail-safe for a PROLONGED stale read. Holding the last split (above) is right for a
# brief blip, but through a multi-hour outage it keeps donating blind — and if staleness
# began mid-ramp it holds a high fraction (over-donation, #70 territory). Past this longer
# grace the controller stops trusting the frozen number and DECAYS the held donation
# fraction toward 0 each advance cycle: when we can't confirm we still need to donate, stop
# wasting hashrate. A fresh fetch resumes normal control. Default 30 min (> the hold grace).
XVB_STALE_DECAY_AFTER_S = float(os.environ.get("XVB_STALE_DECAY_AFTER_S", 1800))

# VIP / PPLNS reserve. To stay "VIP" we must keep finding p2pool shares, so we
# reserve enough hashrate for p2pool to hold a share in the PPLNS window. The bare
# minimum (one expected share per window) is sidechain_difficulty / window_seconds;
# this factor multiplies it for headroom against Poisson variance (2.0 => ~2
# expected shares, P(zero) ~ 13%). Donation is capped so p2pool always keeps at
# least this. Falls back to XVB_MAX_DONATION_FRACTION when difficulty is unknown.
XVB_P2POOL_RESERVE_FACTOR = float(os.environ.get("XVB_P2POOL_RESERVE_FACTOR", 2.0))

# Switching overhead (ms) to account for connection ramp-up time
XVB_SWITCH_OVERHEAD_MS = 5000

# --- Data Retention Policies ---
HISTORY_RETENTION_SEC = 30 * 24 * 3600  # 30 Days
# How long an offline worker lingers in the live "Workers Alive" table before it falls off (#182).
# Operates on the live proxy-sourced list. A reconnect re-adds the worker. 1h keeps a
# just-disconnected rig visible (shown as DOWN) but clears ghosts.
WORKER_FALLOFF_SEC = 3600  # 1 Hour

# --- Hashrate averaging windows (#168) ---
# xmrig-proxy's /workers rows expose five native per-worker averaging windows. The chart lets the
# operator pick which one to plot; these keys are the canonical identifiers shared by the collector,
# the storage schema, and the /api/state `avg` query param. Shorter windows show responsiveness (a
# rig dropping/joining spikes within a poll or two); longer windows show the smoothed trend.
HASHRATE_WINDOWS = ["1m", "10m", "1h", "12h", "24h"]
# Default plotted window. 10m is today's headline series, so the default chart is unchanged AND keeps
# its full history (it reuses the original v_p2pool/v_xvb columns below). The other four are captured
# and persisted going FORWARD only — pre-#168 history has no per-window data and reads 0 there, and
# the 12h/24h averages also need that much rig uptime to fill (signposted in the UI).
DEFAULT_HASHRATE_WINDOW = "10m"
# window -> (p2pool column, xvb column) in the history table. 10m maps to the original pair so the
# default view and all existing rows stay intact; the rest are additive columns (see _migrate_db).
HASHRATE_WINDOW_COLUMNS = {
    "1m": ("v_p2pool_1m", "v_xvb_1m"),
    "10m": ("v_p2pool", "v_xvb"),
    "1h": ("v_p2pool_1h", "v_xvb_1h"),
    "12h": ("v_p2pool_12h", "v_xvb_12h"),
    "24h": ("v_p2pool_24h", "v_xvb_24h"),
}

